    {
      "start_time_mmss": "00:28.436",
      "end_time_mmss": "00:35.957",
      "description_text": "Flo osserva tristemente la stanza vuota, stringendo al petto una piccola bambola di pezza."
    },
    {
      "start_time_mmss": "00:38.864",
      "end_time_mmss": "00:41.948",
      "description_text": "Franz solleva il pesante baule scuro."
    },
    {
      "start_time_mmss": "00:46.104",
      "end_time_mmss": "00:49.811",
      "description_text": "Jack stringe la mano della madre sorridendo."
    },
    {
      "start_time_mmss": "00:52.499",
      "end_time_mmss": "00:55.768",
      "description_text": "La famiglia esce dalla grande casa."
    },
    {
      "start_time_mmss": "01:06.556",
      "end_time_mmss": "01:16.879",
      "description_text": "Una carrozza scura attende fuori, con i cavalli impazienti. Il padre, Ernest, carica i bagagli sul retro del veicolo."
