    {
      "start_time_mmss": "01:44.508",
      "end_time_mmss": "01:55.134",
      "description_text": "I bambini salgono sulla carrozza uno dopo l'altro. Marie resta sulla soglia, salutandoli debolmente con la mano destra alzata."
    }
  ]
